/* Pages: network first (fresh content when online), cache when offline.
   Everything else: cache first, refreshed in the background. Query strings are ignored. */
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const key = url.origin + url.pathname;
  const isPage = req.mode === 'navigate' || url.pathname.endsWith('.html') || url.pathname.endsWith('/');
  e.respondWith((async () => {
    const cache = await caches.open(VERSION);
    const cached = await cache.match(key);
    const fromNet = fetch(req).then(r => {
      if (r && r.status === 200 && r.type === 'basic') cache.put(key, r.clone()).catch(() => {});
      return r;
    });
    if (isPage) {
      try { return await fromNet; } catch (err) { return cached || new Response('Нет сети', { status: 503 }); }
    }
    if (cached) { fromNet.catch(() => {}); return cached; }
    try { return await fromNet; } catch (err) { return new Response('', { status: 504 }); }
  })());
});
